-- The sheet's late percent: an overdue claim gains this percent of its figure for every full 30 days
-- it is overdue (two decimals). It starts at 0.00.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(5, 2) DEFAULT 0.00 NOT NULL;
-- A person's patrons: other people on the same sheet they have named, each at most once.
CREATE TABLE person_patron (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    CHECK (person_id <> patron_id)
);
CREATE UNIQUE INDEX person_patron_pair ON person_patron (person_id, patron_id);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, id);
-- A statement taken for a person: the sheet's today when it was taken, their due-total then (null:
-- n/a) and how many of their claims counted. A person's statements are listed in the order taken (id).
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    taken_on  DATE           NOT NULL,
    due_total DECIMAL(15, 2),
    claims    INT            NOT NULL,
    taken_by  VARCHAR(200)   NOT NULL
);
CREATE INDEX statement_person ON statement (sheet_id, person_id, id);
-- A claim bound by its person's last statement shows and totals the figure it had then (stated_due,
-- null: n/a) until the next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(15, 2);
-- A person can be put on hold: while held, their open claims count in no live total.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
-- A settled claim's due, fixed when it is settled: its amount times its person's grade's rate then,
-- rounded half up to cents. Later changes to rates (or grades) do not alter it. Open and other
-- claims have none (their due stays live), as does one settled while its grade had no rate.
ALTER TABLE claim ADD COLUMN due DECIMAL(15, 2);
UPDATE claim c SET due = (
    SELECT ROUND(c.amount * r.pct / 100, 2) FROM person p JOIN rate r
        ON r.sheet_id = p.sheet_id AND r.grade = p.grade
    WHERE p.id = c.person_id)
WHERE c.status = 'SETTLED';
-- A claim's status: DRAFT when added; DRAFT -> OPEN -> SETTLED, and DRAFT or OPEN -> VOID. SETTLED
-- and VOID are final. Only OPEN and SETTLED claims count toward claimed and due.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
-- A period of the sheet: a name (unique on the sheet, compared without regard to case) and a from and
-- to date, both inclusive. No two periods of a sheet overlap. A claim belongs to the period whose dates
-- contain its date, or to none.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200) NOT NULL,
    name_key  VARCHAR(200) GENERATED ALWAYS AS (LOWER(name)),
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
-- A person can be retired from a date: a claim of theirs dated after it is refused. Null: not retired.
ALTER TABLE person ADD COLUMN retired_from DATE;
-- The sheet's floor: a claim's live due is at least this (two decimals). It starts at 1.00.
ALTER TABLE sheet ADD COLUMN floor DECIMAL(15, 2) DEFAULT 1.00 NOT NULL;
-- A claim a person makes: an amount (0.00 or more, two decimals), a date and a note (may be
-- empty). Listed under its person newest first (id).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(15, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(1000)  NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
-- The sheet's rate for a grade: a percent with two decimals (0.00 or more). A grade has at most one
-- rate on a sheet; setting it again replaces it. A grade with no rate has none.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- A sheet: everything else in the app is kept per sheet, keyed by its id.
CREATE TABLE sheet (
    id         VARCHAR(100) PRIMARY KEY,
    created_by VARCHAR(100) NOT NULL,
    created_at TIMESTAMP    NOT NULL
);
-- A person on a sheet: a name and a grade (A, B or C). Listed in the order they were added (id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- A rate may carry a from-date: it applies to claims dated on or after it, until a later from-date
-- of the same grade takes over. A rate with no from-date applies from the beginning of time. A grade
-- has at most one rate per from-date (and at most one without one); setting it again replaces it.
ALTER TABLE rate ADD COLUMN from_date DATE;
DROP INDEX rate_sheet_grade;
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_date);
-- A claim's number: given when it is opened, the next on its sheet (1, 2, ...), never reused. A
-- draft has none, and voiding clears it. The sheet keeps the last number it gave out.
ALTER TABLE claim ADD COLUMN number INT;
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
UPDATE claim c SET number = (
    SELECT COUNT(*) FROM claim o
    WHERE o.sheet_id = c.sheet_id AND o.status IN ('OPEN', 'SETTLED') AND o.id <= c.id)
WHERE c.status IN ('OPEN', 'SETTLED');
UPDATE sheet s SET last_claim_number = COALESCE((SELECT MAX(number) FROM claim c WHERE c.sheet_id = s.id), 0);
CREATE UNIQUE INDEX claim_sheet_number ON claim (sheet_id, number);
-- A person's name is unique on the sheet, compared without regard to case. Names are stored with
-- surrounding spaces removed.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- A person's version: moved on by every save, so an edit made from an older version is refused.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
-- The sheet's "today": every date-dependent decision and default date in the sheet uses it, never
-- the real clock. A new sheet starts it at the real date.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE);
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
-- The sheet's clerk limit: a clerk may settle a claim only when its due is at or below it (two
-- decimals). None: no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(15, 2);
-- The role the sheet gives a user name. A name with none is a clerk.
CREATE TABLE sheet_role (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('CLERK', 'STEWARD'))
);
CREATE UNIQUE INDEX sheet_role_sheet_user ON sheet_role (sheet_id, user_name);
-- Who opened a claim: set when it is opened. A draft has none. The user who opened a claim may not
-- settle it (four eyes).
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(255);
-- A period can be closed: its due-total is then fixed at the moment it closed (closed_total), and no
-- claim dated inside it can be added, edited, opened, settled or voided.
ALTER TABLE period ADD COLUMN closed BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(15, 2);
-- The sheet's terms: a claim is due by its date plus this many days. It starts at 14.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
